package com.bank.spark.model;

// Outcome of a read: how many data passes, and whether drift was detected.
public class ReadResult {
    private final String format;
    private final int dataPasses;
    private final boolean driftDetected;

    public ReadResult(String format, int dataPasses, boolean driftDetected) {
        this.format = format;
        this.dataPasses = dataPasses;
        this.driftDetected = driftDetected;
    }

    public String getFormat() { return format; }
    public int getDataPasses() { return dataPasses; }
    public boolean isDriftDetected() { return driftDetected; }
}
