package com.bank.spark.service;

import com.bank.spark.model.ReadResult;
import java.util.List;
import java.util.logging.Logger;

// Models how each read strategy handles schema and passes over data.
public class SchemaReader {

    private static final Logger log = Logger.getLogger(SchemaReader.class.getName());

    // CSV with inferSchema=true: one pass to infer types, one to load → 2 passes.
    public ReadResult readCsvInferred() {
        log.warning("CSV inferSchema=true → reads data TWICE (infer + load)");
        return new ReadResult("CSV(inferred)", 2, false);
    }

    // JSON inference: single pass over a sample; a field outside the sample is missed.
    public ReadResult readJsonInferred(List<String> sampleFields, List<String> actualFields) {
        boolean missed = !sampleFields.containsAll(actualFields);
        if (missed) log.warning("JSON sample inference MISSED a field present outside the sample");
        return new ReadResult("JSON(inferred)", 1, false);
    }

    // Explicit schema: single pass; mismatch with the source is drift caught at read.
    public ReadResult readWithExplicitSchema(List<String> declared, List<String> actual) {
        boolean drift = !declared.equals(actual);
        if (drift) log.severe("Explicit schema: SOURCE DRIFT detected (columns differ) → fail fast");
        else log.info("Explicit schema: single pass, schema matches source");
        return new ReadResult("explicit", 1, drift);
    }
}
