package com.bank.spark;

import com.bank.spark.model.ReadResult;
import com.bank.spark.service.SchemaReader;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: compare inference strategies and explicit schema.
public class SchemaInferenceDemo {

    private static final Logger log = Logger.getLogger(SchemaInferenceDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        SchemaReader reader = new SchemaReader();

        ReadResult csv = reader.readCsvInferred();
        log.info(() -> csv.getFormat() + " used " + csv.getDataPasses() + " data passes");

        ReadResult json = reader.readJsonInferred(
            List.of("txnId", "accountId"),               // sampled fields
            List.of("txnId", "accountId", "channel"));    // actual has an extra field
        log.info(() -> json.getFormat() + " used " + json.getDataPasses() + " data pass");

        // Explicit schema where the source added a 'channel' column → drift caught.
        ReadResult explicit = reader.readWithExplicitSchema(
            List.of("txnId", "accountId", "amount"),      // declared
            List.of("txnId", "accountId", "amount", "channel")); // source changed
        log.info(() -> explicit.getFormat() + " pass=" + explicit.getDataPasses()
                + " driftDetected=" + explicit.isDriftDetected());

        log.info("Schema inference demo complete.");
    }
}
